50	    /// Custom test analyzer that simulates errors
51	    struct ErrorSimulatorAnalyzer {
52	        error_on_event_number: usize,
53	        event_count: AtomicUsize,
54	    }
55	
56	    impl ErrorSimulatorAnalyzer {
57	        fn new(error_on_event_number: usize) -> Self {
58	            Self {
59	                error_on_event_number,
60	                event_count: AtomicUsize::new(0),
61	            }
62	        }
63	    }
64	
65	    #[async_trait]
66	    impl Analyzer for ErrorSimulatorAnalyzer {
67	        async fn process(&mut self, stream: EventStream) -> Result<EventStream, AnalyzerError> {
68	            let error_event = self.error_on_event_number;
69	            let counter = Arc::new(AtomicUsize::new(0));
70	            
71	            let processed_stream = stream.map(move |event| {
72	                let count = counter.fetch_add(1, Ordering::SeqCst) + 1;
73	                if count == error_event {
74	                    // Simulate an error condition but don't actually error out
75	                    // Instead, modify the event to indicate an error occurred
76	                    let mut error_event = event;
77	                    if let Some(data) = error_event.data.as_object_mut() {
78	                        data.insert("analyzer_error".to_string(), json!("Simulated error"));
79	                    }
80	                    error_event
81	                } else {
82	                    event
83	                }
84	            });
85	            
86	            Ok(Box::pin(processed_stream))
87	        }
88	
89	        fn name(&self) -> &str {
90	            "ErrorSimulatorAnalyzer"
91	        }
92	    }
