105	    #[async_trait]
106	    impl Analyzer for FilterAnalyzer {
107	        async fn process(&mut self, stream: EventStream) -> Result<EventStream, AnalyzerError> {
108	            let condition = self.filter_condition.clone();
109	            let filtered_stream = stream.filter(move |event| {
110	                let matches = if condition == "ssl_only" {
111	                    event.source == "ssl"
112	                } else if condition == "even_pids" {
113	                    event.data.get("pid")
114	                        .and_then(|v| v.as_u64())
115	                        .map(|pid| pid % 2 == 0)
116	                        .unwrap_or(false)
117	                } else {
118	                    true // No filter
119	                };
120	                futures::future::ready(matches)
121	            });
122	            
123	            Ok(Box::pin(filtered_stream))
124	        }
125	
126	        fn name(&self) -> &str {
127	            "FilterAnalyzer"
128	        }
129	    }
