288	    #[tokio::test]
289	    async fn test_analyzer_chain_streaming_behavior() {
290	        // Test that events are processed in streaming fashion, not batched
291	        use std::sync::Arc;
292	        use tokio::sync::Mutex;
293	        use std::time::Instant;
294	        
295	        let event_timestamps = Arc::new(Mutex::new(Vec::new()));
296	        
297	        // Custom analyzer that records processing timestamps
298	        struct TimestampRecorderAnalyzer {
299	            timestamps: Arc<Mutex<Vec<(usize, Instant)>>>,
300	            counter: Arc<AtomicUsize>,
301	        }
302	        
303	        impl TimestampRecorderAnalyzer {
304	            fn new(timestamps: Arc<Mutex<Vec<(usize, Instant)>>>) -> Self {
305	                Self {
306	                    timestamps,
307	                    counter: Arc::new(AtomicUsize::new(0)),
308	                }
309	            }
310	        }
311	        
312	        #[async_trait]
313	        impl Analyzer for TimestampRecorderAnalyzer {
314	            async fn process(&mut self, stream: EventStream) -> Result<EventStream, AnalyzerError> {
315	                let timestamps = self.timestamps.clone();
316	                let counter = self.counter.clone();
317	                
318	                let recorded_stream = stream.map(move |event| {
319	                    let count = counter.fetch_add(1, Ordering::SeqCst);
320	                    let timestamp = Instant::now();
321	                    
322	                    let timestamps_clone = timestamps.clone();
323	                    tokio::spawn(async move {
324	                        let mut guard = timestamps_clone.lock().await;
325	                        guard.push((count, timestamp));
326	                    });
327	                    
328	                    event
329	                });
330	                
331	                Ok(Box::pin(recorded_stream))
332	            }
333	            
334	            fn name(&self) -> &str {
335	                "TimestampRecorderAnalyzer"
336	            }
337	        }
338	        
339	        let timestamps_clone = Arc::clone(&event_timestamps);
340	        
341	        let mut runner = FakeRunner::new()
342	            .event_count(5) // 10 events total
343	            .delay_ms(100) // 100ms delay to ensure streaming behavior is observable
344	            .add_analyzer(Box::new(TimestampRecorderAnalyzer::new(timestamps_clone)))
345	            .add_analyzer(Box::new(OutputAnalyzer::new()));
346	
347	        let start_time = Instant::now();
348	        let stream = runner.run().await.unwrap();
349	        let events: Vec<_> = stream.collect().await;
350	        let total_time = start_time.elapsed();
351	        
352	        // Wait a bit for async timestamp recording to complete
353	        tokio::time::sleep(Duration::from_millis(50)).await;
354	        
355	        let timestamps_guard = event_timestamps.lock().await;
356	        
357	        println!("Streaming Behavior Test Results:");
358	        println!("Total events: {}", events.len());
359	        println!("Total time: {:?}", total_time);
360	        println!("Recorded timestamps: {}", timestamps_guard.len());
361	        
362	        // Verify streaming behavior - events should arrive over time, not all at once
363	        assert!(timestamps_guard.len() >= 5, "Should have recorded multiple timestamps");
364	        
365	        if timestamps_guard.len() >= 2 {
366	            let first_event_time = timestamps_guard[0].1;
367	            let last_event_time = timestamps_guard[timestamps_guard.len() - 1].1;
368	            let processing_span = last_event_time.duration_since(first_event_time);
369	            
370	            println!("Processing span: {:?}", processing_span);
371	            
372	            // Should take some time due to delays, indicating streaming behavior
373	            assert!(processing_span >= Duration::from_millis(50), 
374	                "Events should be processed over time, not all at once");
375	        }
376	        
377	        println!("✅ Streaming behavior test completed!");
378	    }
