225	        Commands::Trace { ssl, ssl_uid, pid, comm, ssl_filter, ssl_handshake, ssl_http, ssl_raw_data, process, duration, mode, http_filter, disable_auth_removal, output, quiet, rotate_logs, max_log_size, server, server_port, log_file } => run_trace(&binary_extractor, *ssl, *pid, *ssl_uid, comm.as_deref(), ssl_filter, *ssl_handshake, *ssl_http, *ssl_raw_data, *process, *duration, *mode, http_filter, *disable_auth_removal, output.as_deref(), *quiet, *rotate_logs, *max_log_size, *server, *server_port, log_file.as_deref()).await.map_err(convert_runner_error)?,
226	        Commands::Record { comm, output, rotate_logs, max_log_size, server_port, log_file } => {
227	            // Predefined filter patterns optimized for agent monitoring
228	            let http_filter_patterns = vec![
229	                "request.path_prefix=/v1/rgstr | response.status_code=202 | request.method=HEAD | response.body=".to_string(),
230	            ];
231	            let ssl_filter_patterns = vec![
232	                "data=0\\r\\n\\r\\n | data.type=binary".to_string(),
233	            ];
234	            
235	            run_trace(&binary_extractor, true, None, None, Some(comm), &ssl_filter_patterns, false, true, false, true, None, None, &http_filter_patterns, false, Some(output), true, *rotate_logs, *max_log_size, true, *server_port, log_file.as_deref().or(Some(output))).await.map_err(convert_runner_error)?
236	        },
