243	/// Show raw SSL events as JSON with optional chunk merging and HTTP parsing
244	async fn run_raw_ssl(binary_extractor: &BinaryExtractor, enable_chunk_merger: bool, enable_http_parser: bool, include_raw_data: bool, http_filter_patterns: &Vec<String>, disable_auth_removal: bool, ssl_filter_patterns: &Vec<String>, quiet: bool, rotate_logs: bool, max_log_size: u64, enable_server: bool, server_port: u16, log_file: Option<&str>, args: &Vec<String>) -> Result<(), RunnerError> {
245	    println!("Raw SSL Events");
246	    println!("{}", "=".repeat(60));
247	    
248	    let mut ssl_runner = SslRunner::from_binary_extractor(binary_extractor.get_sslsniff_path());
249	    
250	    // Set up event broadcasting for server if enabled
251	    let (event_sender, _event_receiver) = broadcast::channel(1000);
252	    
253	    // Add additional arguments if provided
254	    if !args.is_empty() {
255	        ssl_runner = ssl_runner.with_args(args);
256	    }
257	    
258	    // Add SSL filter if patterns are provided (must be first after SSL runner)
259	    if !ssl_filter_patterns.is_empty() {
260	        ssl_runner = ssl_runner.add_analyzer(Box::new(SSLFilter::with_patterns(ssl_filter_patterns.clone())));
261	    }
262	    
263	    // Add analyzers based on flags - when HTTP parser is enabled, always enable SSE merge first
264	    if enable_http_parser {
265	        ssl_runner = ssl_runner.add_analyzer(Box::new(SSEProcessor::new_with_timeout(30000)));
266	        
267	        // Create HTTP parser with appropriate configuration
268	        let http_parser = if include_raw_data {
269	            HTTPParser::new()
270	        } else {
271	            HTTPParser::new().disable_raw_data()
272	        };
273	        ssl_runner = ssl_runner.add_analyzer(Box::new(http_parser));
274	        
275	        // Add HTTP filter if patterns are provided
276	        if !http_filter_patterns.is_empty() {
277	            ssl_runner = ssl_runner.add_analyzer(Box::new(HTTPFilter::with_patterns(http_filter_patterns.clone())));
278	        }
279	        
280	        // Add authorization header remover by default (unless disabled)
281	        if !disable_auth_removal {
282	            ssl_runner = ssl_runner.add_analyzer(Box::new(AuthHeaderRemover::new()));
283	        }
284	        
285	        let raw_data_info = if include_raw_data { " (with raw data)" } else { "" };
286	        let ssl_filter_info = if !ssl_filter_patterns.is_empty() { " with SSL filtering," } else { "" };
287	        let http_filter_info = if !http_filter_patterns.is_empty() { " and HTTP filtering" } else { "" };
288	        println!("Starting SSL event stream{} with SSE processing, HTTP parsing{}{} enabled (press Ctrl+C to stop):", ssl_filter_info, raw_data_info, http_filter_info);
289	    } else if enable_chunk_merger {
290	        ssl_runner = ssl_runner.add_analyzer(Box::new(SSEProcessor::new_with_timeout(30000)));
291	        let ssl_filter_info = if !ssl_filter_patterns.is_empty() { " with SSL filtering and" } else { " with" };
292	        println!("Starting SSL event stream{} SSE processing enabled (press Ctrl+C to stop):", ssl_filter_info);
293	    } else {
294	        let ssl_filter_info = if !ssl_filter_patterns.is_empty() { " with SSL filtering and" } else { " with" };
295	        println!("Starting SSL event stream{} raw JSON output (press Ctrl+C to stop):", ssl_filter_info);
296	    }
297	    
298	    ssl_runner = ssl_runner
299	        .add_analyzer(Box::new(
300	            if rotate_logs {
301	                FileLogger::with_max_size("ssl.log", max_log_size).unwrap()
302	            } else {
303	                FileLogger::new("ssl.log").unwrap()
304	            }
305	        ));
306	    
307	    if !quiet {
308	        ssl_runner = ssl_runner.add_analyzer(Box::new(OutputAnalyzer::new()));
309	    }
310	    
311	    // Start web server if enabled
312	    let _server_handle = start_web_server_if_enabled(enable_server, server_port, log_file.or(Some("ssl.log")), event_sender.clone()).await
313	        .map_err(|e| RunnerError::from(format!("Failed to start server: {}", e)))?;
314	    
315	    let mut stream = ssl_runner.run().await?;
316	    
317	    // Consume the stream to actually process events
318	    while let Some(event) = stream.next().await {
319	        // Forward events to web server if enabled
320	        if enable_server {
321	            let _ = event_sender.send(event);
322	        }
323	    }
324	    
325	    Ok(())
326	}
