6	/// AgentRunner composes multiple runners into a single unified stream
7	/// with optional global analyzers applied to the merged stream
8	pub struct AgentRunner {
9	    runners: Vec<Box<dyn Runner>>,
10	    analyzers: Vec<Box<dyn Analyzer>>,
11	    name: String,
12	}
13	
14	impl AgentRunner {
15	    /// Create a new AgentRunner with the given name
16	    pub fn new(name: impl Into<String>) -> Self {
17	        Self {
18	            runners: Vec::new(),
19	            analyzers: Vec::new(),
20	            name: name.into(),
21	        }
22	    }
23	    
24	    /// Add a pre-configured runner with its analyzer chain
25	    pub fn add_runner(mut self, runner: Box<dyn Runner>) -> Self {
26	        self.runners.push(runner);
27	        self
28	    }
29	    
30	    /// Add analyzer that will be applied to the merged stream
31	    pub fn add_global_analyzer(mut self, analyzer: Box<dyn Analyzer>) -> Self {
32	        self.analyzers.push(analyzer);
33	        self
34	    }
35	    
36	    /// Get the number of configured runners
37	    pub fn runner_count(&self) -> usize {
38	        self.runners.len()
39	    }
40	    
41	    /// Get the number of configured global analyzers
42	    pub fn analyzer_count(&self) -> usize {
43	        self.analyzers.len()
44	    }
45	}
46	
47	#[async_trait]
48	impl Runner for AgentRunner {
49	    async fn run(&mut self) -> Result<EventStream, RunnerError> {
50	        if self.runners.is_empty() {
51	            return Err("No runners configured for AgentRunner".into());
52	        }
53	        
54	        // Start all runners concurrently and collect their streams
55	        let mut streams = Vec::new();
56	        for runner in &mut self.runners {
57	            let stream = runner.run().await?;
58	            streams.push(stream);
59	        }
60	        
61	        // Merge all streams into a single stream
62	        let merged_stream = select_all(streams);
63	        
64	        // Apply global analyzers to the merged stream
65	        let mut final_stream = Box::pin(merged_stream) as EventStream;
66	        for analyzer in &mut self.analyzers {
67	            final_stream = analyzer.process(final_stream).await
68	                .map_err(|e| format!("Global analyzer error: {}", e))?;
69	        }
70	        
71	        Ok(final_stream)
72	    }
73	    
74	    fn add_analyzer(mut self, analyzer: Box<dyn Analyzer>) -> Self {
75	        self.analyzers.push(analyzer);
76	        self
77	    }
78	    
79	    fn name(&self) -> &str {
80	        &self.name
81	    }
82	    
83	    fn id(&self) -> String {
84	        format!("agent-{}", self.name)
85	    }
86	}
