201	        use std::sync::Arc;
202	        use tokio::sync::Mutex;
203	        use std::time::Instant;
204	        
205	        let event_timestamps = Arc::new(Mutex::new(Vec::new()));
206	        
207	        // Custom analyzer that records timestamps
208	        struct TimestampRecorder {
209	            timestamps: Arc<Mutex<Vec<Instant>>>,
210	        }
211	        
212	        impl TimestampRecorder {
213	            fn new(timestamps: Arc<Mutex<Vec<Instant>>>) -> Self {
214	                Self { timestamps }
215	            }
216	        }
217	        
218	        #[async_trait]
219	        impl Analyzer for TimestampRecorder {
220	            async fn process(&mut self, stream: EventStream) -> Result<EventStream, Box<dyn std::error::Error + Send + Sync>> {
221	                let timestamps = self.timestamps.clone();
222	                let recorded_stream = stream.map(move |event| {
223	                    let timestamps_clone = timestamps.clone();
224	                    tokio::spawn(async move {
225	                        let mut guard = timestamps_clone.lock().await;
226	                        guard.push(Instant::now());
227	                    });
228	                    event
229	                });
230	                Ok(Box::pin(recorded_stream))
231	            }
232	            
233	            fn name(&self) -> &str {
234	                "TimestampRecorder"
235	            }
236	        }
237	        
