239	            .event_count(3)
240	            .delay_ms(50); // Longer delay to ensure streaming behavior
241	        
242	        let mut agent = AgentRunner::new("streaming-test")
243	            .add_runner(Box::new(fake_runner))
244	            .add_global_analyzer(Box::new(TimestampRecorder::new(Arc::clone(&event_timestamps))))
245	            .add_global_analyzer(Box::new(OutputAnalyzer::new()));
246	        
247	        let start_time = Instant::now();
248	        let stream = agent.run().await.unwrap();
249	        let events: Vec<_> = stream.collect().await;
250	        let total_time = start_time.elapsed();
251	        
252	        // Wait for async timestamp recording to complete
253	        tokio::time::sleep(Duration::from_millis(100)).await;
254	        
255	        assert_eq!(events.len(), 6); // 3 event_count × 2 events per count (request + response)
256	        
257	        let timestamps_guard = event_timestamps.lock().await;
258	        assert!(timestamps_guard.len() >= 3, "Should have recorded multiple timestamps");
259	        
260	        // Should take some time due to delays, indicating streaming behavior
261	        assert!(total_time >= Duration::from_millis(100), "Should demonstrate streaming behavior");
262	    }
