375	async fn run_trace(
376	    binary_extractor: &BinaryExtractor,
377	    ssl_enabled: bool,
378	    pid: Option<u32>,
379	    ssl_uid: Option<u32>,
380	    comm: Option<&str>,
381	    ssl_filter: &[String],
382	    ssl_handshake: bool,
383	    ssl_http: bool,
384	    ssl_raw_data: bool,
385	    process_enabled: bool,
386	    duration: Option<u32>,
387	    mode: Option<u32>,
388	    http_filter: &[String],
389	    disable_auth_removal: bool,
390	    output: Option<&str>,
391	    quiet: bool,
392	    rotate_logs: bool,
393	    max_log_size: u64,
394	    enable_server: bool,
395	    server_port: u16,
396	    log_file: Option<&str>,
397	) -> Result<(), RunnerError> {
398	    println!("Trace Monitoring");
399	    println!("{}", "=".repeat(60));
400	    
401	    // Set up event broadcasting for server if enabled
402	    let (event_sender, _event_receiver) = broadcast::channel(1000);
403	    
404	    let mut agent = AgentRunner::new("trace");
405	    
406	    // Add SSL runner if enabled
407	    if ssl_enabled {
408	        let mut ssl_runner = SslRunner::from_binary_extractor(binary_extractor.get_sslsniff_path());
409	        
410	        // Configure SSL runner arguments (sslsniff supports -p, -u, -c, -h, -v)
411	        let mut ssl_args = Vec::new();
412	        if let Some(pid_filter) = pid {
413	            ssl_args.extend(["-p".to_string(), pid_filter.to_string()]);
414	        }
415	        if let Some(uid_filter) = ssl_uid {
416	            ssl_args.extend(["-u".to_string(), uid_filter.to_string()]);
417	        }
418	        if let Some(comm_filter) = comm {
419	            ssl_args.extend(["-c".to_string(), comm_filter.to_string()]);
420	        }
421	        if ssl_handshake {
422	            ssl_args.push("--handshake".to_string());
423	        }
424	        if !ssl_args.is_empty() {
425	            ssl_runner = ssl_runner.with_args(&ssl_args);
426	        }
427	        
428	        // Add SSL-specific analyzers
429	        if !ssl_filter.is_empty() {
430	            ssl_runner = ssl_runner.add_analyzer(Box::new(SSLFilter::with_patterns(ssl_filter.to_vec())));
431	        }
432	        
433	        if ssl_http {
434	            ssl_runner = ssl_runner.add_analyzer(Box::new(SSEProcessor::new_with_timeout(30000)));
435	            
436	            let http_parser = if ssl_raw_data {
437	                HTTPParser::new()
438	            } else {
439	                HTTPParser::new().disable_raw_data()
440	            };
441	            ssl_runner = ssl_runner.add_analyzer(Box::new(http_parser));
442	            
443	            // Add HTTP filter to SSL runner if patterns are provided
444	            if !http_filter.is_empty() {
445	                ssl_runner = ssl_runner.add_analyzer(Box::new(HTTPFilter::with_patterns(http_filter.to_vec())));
446	            }
447	            
448	            // Add authorization header remover by default (unless disabled)
449	            if !disable_auth_removal {
450	                ssl_runner = ssl_runner.add_analyzer(Box::new(AuthHeaderRemover::new()));
451	            }
452	        }
453	        
454	        agent = agent.add_runner(Box::new(ssl_runner));
455	        let http_filter_info = if ssl_http && !http_filter.is_empty() { 
456	            format!(" with {} HTTP filter patterns", http_filter.len()) 
457	        } else { 
458	            String::new() 
459	        };
460	        println!("✓ SSL monitoring enabled{}", http_filter_info);
461	    }
462	    
463	    // Add process runner if enabled
464	    if process_enabled {
465	        let mut process_runner = ProcessRunner::from_binary_extractor(binary_extractor.get_process_path());
466	        
467	        // Configure process runner arguments (process supports -c, -d, -m, -v)
468	        let mut process_args = Vec::new();
469	        if let Some(comm_filter) = comm {
470	            process_args.extend(["-c".to_string(), comm_filter.to_string()]);
471	        }
472	        if let Some(duration_filter) = duration {
473	            process_args.extend(["-d".to_string(), duration_filter.to_string()]);
474	        }
475	        if let Some(mode_filter) = mode {
476	            process_args.extend(["-m".to_string(), mode_filter.to_string()]);
477	        }
478	        if !process_args.is_empty() {
479	            process_runner = process_runner.with_args(&process_args);
480	        }
481	        
482	        agent = agent.add_runner(Box::new(process_runner));
483	        println!("✓ Process monitoring enabled");
484	    }
485	    
486	    // Ensure at least one runner is enabled (this check is now redundant but kept for safety)
487	    if !ssl_enabled && !process_enabled {
488	        return Err("At least one monitoring type must be enabled (--ssl or --process)".into());
489	    }
490	    
491	    // Add global analyzers (HTTP filter is now added to SSL runner instead)
492	    
493	    if let Some(output_path) = output {
494	        agent = agent.add_global_analyzer(Box::new(
495	            if rotate_logs {
496	                FileLogger::with_max_size(output_path, max_log_size).unwrap()
497	            } else {
498	                FileLogger::new(output_path).unwrap()
499	            }
500	        ));
501	        println!("✓ Logging to file: {}", output_path);
502	    }
503	    
504	    if !quiet {
505	        agent = agent.add_global_analyzer(Box::new(OutputAnalyzer::new()));
506	        println!("✓ Console output enabled");
507	    }
508	    
509	    println!("{}", "=".repeat(60));
510	    println!("Starting flexible trace monitoring with {} runners and {} global analyzers...", 
511	             agent.runner_count(), agent.analyzer_count());
512	    println!("Press Ctrl+C to stop");
513	    
514	    // Start web server if enabled
515	    let _server_handle = start_web_server_if_enabled(enable_server, server_port, log_file.or(Some("ssl.log")), event_sender.clone()).await
516	        .map_err(|e| RunnerError::from(format!("Failed to start server: {}", e)))?;
517	    
518	    let mut stream = agent.run().await?;
519	    
520	    // Consume the stream to actually process events
521	    while let Some(event) = stream.next().await {
522	        // Forward events to web server if enabled
523	        if enable_server {
524	            let _ = event_sender.send(event);
525	        }
526	    }
527	    
528	    Ok(())
529	}
