532	// Shared server management function
533	async fn start_web_server_if_enabled(
534	    enable_server: bool,
535	    port: u16,
536	    log_file: Option<&str>,
537	    event_sender: broadcast::Sender<crate::framework::core::Event>,
538	) -> Result<Option<tokio::task::JoinHandle<()>>, Box<dyn std::error::Error>> {
539	    if !enable_server {
540	        return Ok(None);
541	    }
542	
543	    let addr = format!("127.0.0.1:{}", port).parse()
544	        .map_err(|e| format!("Invalid server address: {}", e))?;
545	    
546	    let web_server = WebServer::new(event_sender, log_file).map_err(|e| format!("Failed to create web server: {}", e))?;
547	    
548	    println!("🌐 Starting web server on http://{}", addr);
549	    println!("   Frontend will be available once the server starts");
550	    
551	    let server_handle = tokio::spawn(async move {
552	        if let Err(e) = web_server.start(addr).await {
553	            eprintln!("❌ Web server error: {}", e);
554	        }
555	    });
556	    
557	    // Give the server a moment to start
558	    tokio::time::sleep(tokio::time::Duration::from_millis(100)).await;
559	    
560	    Ok(Some(server_handle))
561	}
