146	#[async_trait]
147	impl Runner for FakeRunner {
148	    async fn run(&mut self) -> Result<EventStream, RunnerError> {
149	        eprintln!("FakeRunner: Starting to generate {} fake SSL event pairs with {}ms delay", 
150	            self.event_count, self.delay_ms);
151	        
152	        let event_count = self.event_count;
153	        let delay_ms = self.delay_ms;
154	        
155	        // Create event stream using a simple generator
156	        let event_stream = async_stream::stream! {
157	            for i in 0..event_count {
158	                eprintln!("FakeRunner: Generating request/response pair #{}", i + 1);
159	                
160	                // Generate and yield request
161	                let request_event = Self::generate_ssl_request(i);
162	                eprintln!("FakeRunner: Yielding request event #{} (PID: {})", 
163	                    i + 1, request_event.data["pid"].as_u64().unwrap_or(0));
164	                yield request_event;
165	                
166	                // Small delay between request and response
167	                sleep(Duration::from_millis(delay_ms / 4)).await;
168	                
169	                // Generate and yield response  
170	                let response_event = Self::generate_ssl_response(i);
171	                eprintln!("FakeRunner: Yielding response event #{} (PID: {})", 
172	                    i + 1, response_event.data["pid"].as_u64().unwrap_or(0));
173	                yield response_event;
174	                
175	                // Longer delay between pairs (except for the last pair)
176	                if i < event_count - 1 {
177	                    sleep(Duration::from_millis(delay_ms)).await;
178	                }
179	            }
180	            
181	            eprintln!("FakeRunner: Completed generating {} request/response pairs", event_count);
182	        };
183	        
184	        // Process through analyzer chain
185	        eprintln!("FakeRunner: Processing through {} analyzers", self.analyzers.len());
186	        AnalyzerProcessor::process_through_analyzers(Box::pin(event_stream), &mut self.analyzers).await
187	    }
