15	/// Common binary executor for runners - now supports streaming
16	pub struct BinaryExecutor {
17	    binary_path: String,
18	    additional_args: Vec<String>,
19	    runner_name: Option<String>,
20	}
21	
22	impl BinaryExecutor {
23	    pub fn new(binary_path: String) -> Self {
24	        Self { 
25	            binary_path,
26	            additional_args: Vec::new(),
27	            runner_name: None,
28	        }
29	    }
30	
31	    /// Add additional command-line arguments
32	    pub fn with_args(mut self, args: &[String]) -> Self {
33	        self.additional_args = args.to_vec();
34	        self
35	    }
36	
37	    /// Set runner name for debugging purposes
38	    pub fn with_runner_name(mut self, name: String) -> Self {
39	        self.runner_name = Some(name);
40	        self
41	    }
42	
43	    /// Execute binary and get raw JSON stream
44	    pub async fn get_json_stream(&self) -> Result<JsonStream, RunnerError> {
45	        // Log the actual exec command with all arguments
46	        if self.additional_args.is_empty() {
47	            log::info!("Executing binary: {}", self.binary_path);
48	        } else {
49	            log::info!("Executing binary: {} {}", self.binary_path, self.additional_args.join(" "));
50	        }
51	        
52	        let mut cmd = TokioCommand::new(&self.binary_path);
53	        cmd.stdout(Stdio::piped())
54	           .stderr(Stdio::piped());
55	        
56	        // Add additional arguments if any
57	        if !self.additional_args.is_empty() {
58	            cmd.args(&self.additional_args);
59	            debug!("Added arguments: {:?}", self.additional_args);
60	        }
61	        
62	        let mut child = cmd.spawn()
63	            .map_err(|e| Box::new(std::io::Error::new(
64	                std::io::ErrorKind::Other, 
65	                format!("Failed to start binary: {}", e)
66	            )) as RunnerError)?;
67	            
68	        let stdout = child.stdout.take()
69	            .ok_or_else(|| Box::new(std::io::Error::new(
70	                std::io::ErrorKind::Other, 
71	                "Failed to get stdout"
72	            )) as RunnerError)?;
73	        
74	        if let Some(pid) = child.id() {
75	            debug!("Binary started with PID: Some({})", pid);
76	        }
77	        
78	        // Clone needed data for the stream
79	        let runner_name = self.runner_name.clone();
80	        let binary_path = self.binary_path.clone();
81	
82	        let stream = async_stream::stream! {
83	            let mut reader = BufReader::new(stdout);
84	            let mut line = String::new();
85	            let mut line_count = 0;
86	            
87	            debug!("Reading from binary stdout");
88	            
89	            loop {
90	                line.clear();
91	                
92	                match reader.read_line(&mut line).await {
93	                    Ok(0) => {
94	                        debug!("Binary stdout closed (EOF)");
95	                        break;
96	                    }
97	                    Ok(_) => {
98	                        line_count += 1;
99	                        let trimmed = line.trim();
100	                        
101	                        if !trimmed.is_empty() {
102	                            debug!("Line {}: {}", line_count, 
103	                                if trimmed.len() > 100 { 
104	                                    format!("{}...", &trimmed[..100]) 
105	                                } else { 
106	                                    trimmed.to_string() 
107	                                }
108	                            );
109	                            
110	                            // Try to parse as JSON
111	                            if trimmed.starts_with('{') && trimmed.ends_with('}') {
112	                                match serde_json::from_str::<serde_json::Value>(trimmed) {
113	                                    Ok(json_value) => {
114	                                        debug!("Parsed JSON value");
115	                                        yield json_value;
116	                                    }
117	                                    Err(e) => {
118	                                        log::warn!("Failed to parse JSON from line {}: {} - Line: {}", 
119	                                            line_count, e,
120	                                            if trimmed.len() > 200 { 
121	                                                format!("{}...", &trimmed[..200]) 
122	                                            } else { 
123	                                                trimmed.to_string() 
124	                                            }
125	                                        );
126	                                    }
127	                                }
128	                            } else {
129	                                // Check if this might be a stderr message or debug output
130	                                if trimmed.contains("error") || trimmed.contains("warn") || 
131	                                   trimmed.contains("failed") || trimmed.contains("Error:") {
132	                                    log::warn!("Possible error message from binary at line {}: {}", 
133	                                        line_count, trimmed);
134	                                } else {
135	                                    log::warn!("Skipping non-JSON line {} from binary: {}", 
136	                                        line_count, 
137	                                        if trimmed.len() > 100 { 
138	                                            format!("{}...", &trimmed[..100]) 
139	                                        } else { 
140	                                            trimmed.to_string() 
141	                                        }
142	                                    );
143	                                }
144	                            }
145	                        }
146	                    }
147	                    Err(e) => {
148	                        // Handle UTF-8 errors gracefully - don't terminate, just warn and continue
149	                        if e.kind() == std::io::ErrorKind::InvalidData {
150	                            let runner_info = runner_name.as_ref()
151	                                .map(|name| format!("[{}] ", name))
152	                                .unwrap_or_else(|| format!("[{}] ", 
153	                                    std::path::Path::new(&binary_path)
154	                                        .file_name()
155	                                        .and_then(|n| n.to_str())
156	                                        .unwrap_or("unknown")
157	                                ));
158	                            
159	                            // Try to recover partial data up to the invalid UTF-8 sequence
160	                            let raw_bytes = line.as_bytes();
161	                            let valid_up_to = String::from_utf8_lossy(raw_bytes);
162	                            
163	                            // If we have a partial JSON object, try to parse it
164	                            if valid_up_to.trim_start().starts_with('{') {
165	                                // Find the position of the invalid UTF-8
166	                                let mut valid_len = 0;
167	                                for i in 0..raw_bytes.len() {
168	                                    if std::str::from_utf8(&raw_bytes[0..=i]).is_ok() {
169	                                        valid_len = i + 1;
170	                                    } else {
171	                                        break;
172	                                    }
173	                                }
174	                                
175	                                if valid_len > 0 {
176	                                    if let Ok(valid_str) = std::str::from_utf8(&raw_bytes[0..valid_len]) {
177	                                        log::debug!("Recovered {} valid UTF-8 bytes before error", valid_len);
178	                                        // Try to parse the valid portion
179	                                        if let Ok(json_value) = serde_json::from_str::<serde_json::Value>(valid_str.trim()) {
180	                                            log::info!("Successfully recovered partial JSON despite UTF-8 error");
181	                                            yield json_value;
182	                                            continue;
183	                                        }
184	                                    }
185	                                }
186	                            }
187	                            
188	                            // Log detailed error information
189	                            let hex_preview = raw_bytes.iter()
190	                                .take(64) // Show more context
191	                                .map(|b| format!("{:02x}", b))
192	                                .collect::<Vec<_>>()
193	                                .join(" ");
194	                            
195	                            log::warn!(
196	                                "{}Invalid UTF-8 at line {} (attempted recovery failed). Hex preview: {}",
197	                                runner_info, line_count + 1, hex_preview
198	                            );
199	                            
200	                            // Clear the line buffer and continue
201	                            line.clear();
202	                            continue;
203	                        } else if e.kind() == std::io::ErrorKind::UnexpectedEof {
204	                            // Handle partial reads at EOF gracefully
205	                            if !line.is_empty() {
206	                                let trimmed = line.trim();
207	                                if trimmed.starts_with('{') && trimmed.ends_with('}') {
208	                                    // Try to parse incomplete JSON at EOF
209	                                    match serde_json::from_str::<serde_json::Value>(trimmed) {
210	                                        Ok(json_value) => {
211	                                            log::debug!("Parsed final JSON line at EOF");
212	                                            yield json_value;
213	                                        }
214	                                        Err(e) => {
215	                                            log::warn!("Failed to parse final line at EOF: {}", e);
216	                                        }
217	                                    }
218	                                }
219	                            }
220	                            log::debug!("Reached EOF while reading");
221	                            break;
222	                        } else if e.kind() == std::io::ErrorKind::Interrupted {
223	                            // Retry on interrupted system calls
224	                            log::debug!("Read interrupted, retrying...");
225	                            continue;
226	                        } else {
227	                            log::warn!("Error reading from binary: {} (kind: {:?})", e, e.kind());
228	                            break;
229	                        }
230	                    }
231	                }
232	            }
233	            
234	            log::info!("Terminating binary process");
235	            
236	            // Terminate the child process
237	            if let Err(e) = child.kill().await {
238	                log::warn!("Failed to kill binary process: {}", e);
239	            }
240	            
241	            // Wait for process to finish
242	            match child.wait().await {
243	                Ok(status) => {
244	                    debug!("Binary process terminated with status: {}", status);
245	                }
246	                Err(e) => {
247	                    log::warn!("Error waiting for binary process: {}", e);
248	                }
249	            }
250	        };
251	        
252	        Ok(Box::pin(stream))
253	    }
254	
255	
256	
257	}
