259	/// Common analyzer processor for runners
260	pub struct AnalyzerProcessor;
261	
262	impl AnalyzerProcessor {
263	    /// Process events through a chain of analyzers
264	    pub async fn process_through_analyzers(
265	        mut stream: EventStream, 
266	        analyzers: &mut [Box<dyn Analyzer>]
267	    ) -> Result<EventStream, RunnerError> {
268	        // Process through each analyzer in sequence
269	        for analyzer in analyzers.iter_mut() {
270	            stream = analyzer.process(stream).await?;
271	        }
272	        
273	        Ok(stream)
274	    }
275	}

