30	    pub async fn start(&self, addr: SocketAddr) -> std::result::Result<(), Box<dyn std::error::Error + Send + Sync>> {
31	        let listener = TcpListener::bind(addr).await.map_err(|e| Box::new(e) as Box<dyn std::error::Error + Send + Sync>)?;
32	        log::info!("🚀 Frontend server running on http://{}", addr);
33	        
34	        // List embedded assets for debugging
35	        let all_assets = self.assets.list_all_assets();
36	        log::info!("📦 Embedded {} assets from frontend/dist:", all_assets.len());
37	        for asset in all_assets.iter().take(10) {
38	            log::info!("   - {}", asset);
39	        }
40	        if all_assets.len() > 10 {
41	            log::info!("   ... and {} more", all_assets.len() - 10);
42	        }
43	        
44	        loop {
45	            let (stream, _) = listener.accept().await.map_err(|e| Box::new(e) as Box<dyn std::error::Error + Send + Sync>)?;
46	            let assets = Arc::clone(&self.assets);
47	            let event_sender = self.event_sender.clone();
48	            let log_file = self.log_file.clone();
49	            
50	            tokio::spawn(async move {
51	                let io = TokioIo::new(stream);
52	                let service = service_fn(move |req| {
53	                    handle_request(req, assets.clone(), event_sender.clone(), log_file.clone())
54	                });
55	                
56	                if let Err(err) = http1::Builder::new()
57	                    .serve_connection(io, service)
58	                    .await
59	                {
60	                    log::error!("❌ Error serving connection: {:?}", err);
61	                }
62	            });
63	        }
64	    }
65	}
