67	async fn handle_request(
68	    req: Request<hyper::body::Incoming>,
69	    assets: Arc<FrontendAssets>,
70	    event_sender: broadcast::Sender<Event>,
71	    log_file: Option<String>,
72	) -> std::result::Result<Response<Full<Bytes>>, Infallible> {
73	    let path = req.uri().path();
74	    
75	    log::info!("📨 {} {}", req.method(), path);
76	    
77	    match (req.method(), path) {
78	        // API endpoints first
79	        (&Method::GET, "/api/events") => {
80	            serve_events_api(event_sender, log_file).await
81	        }
82	        (&Method::GET, "/api/assets") => {
83	            serve_assets_list(assets).await
84	        }
85	        
86	        // Serve static assets (catch-all for GET requests)
87	        (&Method::GET, _) => {
88	            serve_asset(assets, path).await
89	        }
90	        
91	        // 404 for non-GET methods
92	        _ => {
93	            log::info!("❌ 404 Not Found: {} {}", req.method(), path);
94	            Ok(Response::builder()
95	                .status(StatusCode::NOT_FOUND)
96	                .header("Content-Type", "text/plain")
97	                .body(Full::new(Bytes::from("Not Found")))
98	                .unwrap())
99	        }
100	    }
101	}
