103	async fn serve_asset(
104	    assets: Arc<FrontendAssets>,
105	    path: &str,
106	) -> std::result::Result<Response<Full<Bytes>>, Infallible> {
107	    if let Some(content) = assets.get(path) {
108	        let content_type = assets.get_content_type(path);
109	        log::info!("✅ Serving asset: {} ({})", path, content_type);
110	        Ok(Response::builder()
111	            .header("Content-Type", content_type)
112	            .header("Cache-Control", "public, max-age=31536000")
113	            .body(Full::new(Bytes::from(content.to_vec())))
114	            .unwrap())
115	    } else {
116	        log::info!("❌ Asset not found: {}", path);
117	        Ok(Response::builder()
118	            .status(StatusCode::NOT_FOUND)
119	            .header("Content-Type", "text/plain")
120	            .body(Full::new(Bytes::from("Asset not found")))
121	            .unwrap())
122	    }
123	}
