47	#[async_trait]
48	impl Runner for AgentRunner {
49	    async fn run(&mut self) -> Result<EventStream, RunnerError> {
50	        if self.runners.is_empty() {
51	            return Err("No runners configured for AgentRunner".into());
52	        }
53	        
54	        // Start all runners concurrently and collect their streams
55	        let mut streams = Vec::new();
56	        for runner in &mut self.runners {
57	            let stream = runner.run().await?;
58	            streams.push(stream);
59	        }
60	        
61	        // Merge all streams into a single stream
62	        let merged_stream = select_all(streams);
63	        
64	        // Apply global analyzers to the merged stream
65	        let mut final_stream = Box::pin(merged_stream) as EventStream;
66	        for analyzer in &mut self.analyzers {
67	            final_stream = analyzer.process(final_stream).await
68	                .map_err(|e| format!("Global analyzer error: {}", e))?;
69	        }
70	        
71	        Ok(final_stream)
72	    }
73	    
74	    fn add_analyzer(mut self, analyzer: Box<dyn Analyzer>) -> Self {
75	        self.analyzers.push(analyzer);
76	        self
77	    }
78	    
79	    fn name(&self) -> &str {
80	        &self.name
81	    }
82	    
83	    fn id(&self) -> String {
84	        format!("agent-{}", self.name)
85	    }
86	}
