use super::{Analyzer, AnalyzerError};
use crate::framework::runners::EventStream;
use async_trait::async_trait;
use futures::stream::StreamExt;
use std::sync::Arc;
use std::sync::atomic::{AtomicU64, Ordering};

/// Terminal analyzer that ends the event stream after `max_events` events
/// have passed through it.
///
/// It must be placed at the END of the analyzer chain (after FileLogger and
/// OutputAnalyzer) so that the count reflects events that were actually logged,
/// not raw events before filtering. Once the limit is reached the stream
/// yields `None` immediately (without waiting for another upstream event);
/// dropping the stream tears down upstream runners, which terminate their
/// eBPF child processes.
pub struct MaxEventsLimiter {
    max_events: u64,
    count: Arc<AtomicU64>,
}

impl MaxEventsLimiter {
    /// Create a limiter that stops the stream after `max_events` events.
    pub fn new(max_events: u64) -> Self {
        Self {
            max_events,
            count: Arc::new(AtomicU64::new(0)),
        }
    }

    /// Configured limit.
    #[allow(dead_code)]
    pub fn max_events(&self) -> u64 {
        self.max_events
    }

    /// Number of events that have passed through so far.
    #[allow(dead_code)]
    pub fn count(&self) -> u64 {
        self.count.load(Ordering::Relaxed)
    }

    /// Whether the limit has been reached.
    #[allow(dead_code)]
    pub fn limit_reached(&self) -> bool {
        self.count() >= self.max_events
    }

    /// Shared handle to the counter, usable after `process` consumes the stream.
    #[allow(dead_code)]
    pub fn counter(&self) -> Arc<AtomicU64> {
        Arc::clone(&self.count)
    }
}

#[async_trait]
impl Analyzer for MaxEventsLimiter {
    async fn process(&mut self, stream: EventStream) -> Result<EventStream, AnalyzerError> {
        let count = Arc::clone(&self.count);
        let limit = usize::try_from(self.max_events).unwrap_or(usize::MAX);

        // `take` stops without polling upstream again after the Nth item, so
        // the count only increments for events that are actually yielded.
        let limited = stream
            .map(move |event| {
                count.fetch_add(1, Ordering::Relaxed);
                event
            })
            .take(limit);

        Ok(Box::pin(limited))
    }

    fn name(&self) -> &str {
        "MaxEventsLimiter"
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::framework::core::Event;
    use futures::stream;
    use serde_json::json;

    fn events(n: usize) -> EventStream {
        let v: Vec<Event> = (0..n)
            .map(|i| Event::new("test".to_string(), 1, "test".to_string(), json!({"i": i})))
            .collect();
        Box::pin(stream::iter(v))
    }

    #[tokio::test]
    async fn stops_after_limit() {
        let mut limiter = MaxEventsLimiter::new(3);
        let out: Vec<_> = limiter.process(events(10)).await.unwrap().collect().await;
        assert_eq!(out.len(), 3);
        assert_eq!(limiter.count(), 3);
        assert!(limiter.limit_reached());
    }

    #[tokio::test]
    async fn passes_all_when_under_limit() {
        let mut limiter = MaxEventsLimiter::new(100);
        let out: Vec<_> = limiter.process(events(5)).await.unwrap().collect().await;
        assert_eq!(out.len(), 5);
        assert!(!limiter.limit_reached());
    }

    #[tokio::test]
    async fn ends_without_polling_extra_event() {
        // Upstream never yields a 2nd item; limiter must still terminate after 1.
        let s: EventStream = Box::pin(
            stream::iter(vec![Event::new("t".to_string(), 1, "t".to_string(), json!({}))])
                .chain(stream::pending()),
        );
        let mut limiter = MaxEventsLimiter::new(1);
        let out: Vec<_> = limiter.process(s).await.unwrap().collect().await;
        assert_eq!(out.len(), 1);
    }
}

