183	impl Analyzer for FileLogger {
184	    async fn process(&mut self, stream: EventStream) -> Result<EventStream, AnalyzerError> {
185	        
186	        let file_handle = Arc::clone(&self.file_handle);
187	        let file_path = self.file_path.clone();
188	        let rotation_config = self.rotation_config.clone();
189	        let event_count = Arc::clone(&self.event_count);
190	        
191	        // Process events using map instead of consuming the stream
192	        let processed_stream = stream.map(move |event| {
193	            debug!("FileLogger: Processing event: {:?}", event);
194	            
195	            // Check if we need to rotate logs before processing this event
196	            if let Some(config) = &rotation_config {
197	                let mut count = event_count.lock().unwrap();
198	                *count += 1;
199	                
200	                // Check rotation at intervals
201	                if *count % config.size_check_interval == 0 {
202	                    if let Ok(metadata) = std::fs::metadata(&file_path) {
203	                        if metadata.len() > config.max_file_size {
204	                            // Perform rotation
205	                            Self::perform_rotation(&file_handle, &file_path, config);
206	                        }
207	                    }
208	                }
209	            }
210	            
211	            // Log the event to file
212	            if let Ok(mut file) = file_handle.lock() {
213	                // Convert event to JSON, handling binary data in the "data" field
214	                let event_json = match event.to_json() {
215	                    Ok(json_str) => {
216	                        // Parse and fix data field if it contains binary
217	                        if let Ok(mut parsed) = serde_json::from_str::<serde_json::Value>(&json_str) {
218	                            if let Some(data_obj) = parsed.get_mut("data") {
219	                                if let Some(data_field) = data_obj.get_mut("data") {
220	                                    let data_str = Self::data_to_string(data_field);
221	                                    *data_field = serde_json::Value::String(data_str);
222	                                }
223	                            }
224	                            serde_json::to_string(&parsed).unwrap_or(json_str)
225	                        } else {
226	                            json_str
227	                        }
228	                    }
229	                    Err(e) => {
230	                        format!("{{\"error\":\"Failed to serialize event: {}\"}}", e)
231	                    }
232	                };
233	                
234	                // Write just the JSON without timestamp
235	                let log_entry = format!("{}\n", event_json);
236	
237	                if let Err(e) = file.write_all(log_entry.as_bytes()) {
238	                    eprintln!("FileLogger: Failed to write to {}: {}", file_path, e);
239	                } else if let Err(e) = file.flush() {
240	                    eprintln!("FileLogger: Failed to flush {}: {}", file_path, e);
241	                }
242	            }
243	            
244	            // Pass the event through unchanged
245	            event
246	        });
247	
248	        Ok(Box::pin(processed_stream))
249	    }
