109	    /// Convert binary data to hex string
110	    fn data_to_string(data: &serde_json::Value) -> String {
111	        match data {
112	            serde_json::Value::String(s) => {
113	                // Check if string contains valid UTF-8
114	                if s.chars().all(|c| !c.is_control() || c == '\n' || c == '\r' || c == '\t') {
115	                    s.clone()
116	                } else {
117	                    // Convert to hex if it contains control characters (likely binary)
118	                    format!("HEX:{}", hex::encode(s.as_bytes()))
119	                }
