126	    /// Perform log rotation (static method for use in closures)
127	    fn perform_rotation(
128	        file_handle: &Arc<Mutex<File>>,
129	        file_path: &str,
130	        config: &LogRotationConfig,
131	    ) {
132	        // Try to acquire the file lock for rotation
133	        if let Ok(mut file) = file_handle.lock() {
134	            // Flush and drop the current file handle
135	            let _ = file.flush();
136	            drop(file);
137	            
138	            // Rotate files in reverse order (app.log.2 -> app.log.3, etc.)
139	            for i in (1..config.max_files).rev() {
140	                let old_path = format!("{}.{}", file_path, i);
141	                let new_path = format!("{}.{}", file_path, i + 1);
142	                
143	                if std::path::Path::new(&old_path).exists() {
144	                    if let Err(e) = std::fs::rename(&old_path, &new_path) {
145	                        eprintln!("FileLogger: Failed to rotate {} to {}: {}", old_path, new_path, e);
146	                    }
147	                }
148	            }
149	            
150	            // Move current file to .1
151	            let rotated_path = format!("{}.1", file_path);
152	            if let Err(e) = std::fs::rename(file_path, &rotated_path) {
153	                eprintln!("FileLogger: Failed to rotate current file to {}: {}", rotated_path, e);
154	            }
155	            
156	            // Create new current file
157	            match OpenOptions::new()
158	                .create(true)
159	                .write(true)
160	                .truncate(true)
161	                .open(file_path)
162	            {
163	                Ok(new_file) => {
164	                    *file_handle.lock().unwrap() = new_file;
165	                }
166	                Err(e) => {
167	                    eprintln!("FileLogger: Failed to create new log file after rotation: {}", e);
168	                }
169	            }
170	            
171	            // Cleanup old files beyond max_files limit
172	            let cleanup_path = format!("{}.{}", file_path, config.max_files + 1);
173	            if std::path::Path::new(&cleanup_path).exists() {
174	                if let Err(e) = std::fs::remove_file(&cleanup_path) {
175	                    eprintln!("FileLogger: Failed to cleanup old log file {}: {}", cleanup_path, e);
176	                }
177	            }
178	        }
179	    }
180	}
