8	/// Terminal analyzer that ends the event stream after `max_events` events
9	/// have passed through it.
10	///
11	/// It must be placed at the END of the analyzer chain (after FileLogger and
12	/// OutputAnalyzer) so that the count reflects events that were actually logged,
13	/// not raw events before filtering. Once the limit is reached the stream
14	/// yields `None` immediately (without waiting for another upstream event);
15	/// dropping the stream tears down upstream runners, which terminate their
16	/// eBPF child processes.
17	pub struct MaxEventsLimiter {
18	    max_events: u64,
19	    count: Arc<AtomicU64>,
20	}
21	
22	impl MaxEventsLimiter {
23	    /// Create a limiter that stops the stream after `max_events` events.
24	    pub fn new(max_events: u64) -> Self {
25	        Self {
26	            max_events,
27	            count: Arc::new(AtomicU64::new(0)),
28	        }
29	    }
30	
31	    /// Configured limit.
32	    #[allow(dead_code)]
33	    pub fn max_events(&self) -> u64 {
34	        self.max_events
35	    }
36	
37	    /// Number of events that have passed through so far.
38	    #[allow(dead_code)]
39	    pub fn count(&self) -> u64 {
40	        self.count.load(Ordering::Relaxed)
41	    }
42	
43	    /// Whether the limit has been reached.
44	    #[allow(dead_code)]
45	    pub fn limit_reached(&self) -> bool {
46	        self.count() >= self.max_events
47	    }
48	
49	    /// Shared handle to the counter, usable after `process` consumes the stream.
50	    #[allow(dead_code)]
51	    pub fn counter(&self) -> Arc<AtomicU64> {
52	        Arc::clone(&self.count)
53	    }
54	}
