56	#[async_trait]
57	impl Analyzer for MaxEventsLimiter {
58	    async fn process(&mut self, stream: EventStream) -> Result<EventStream, AnalyzerError> {
59	        let count = Arc::clone(&self.count);
60	        let limit = usize::try_from(self.max_events).unwrap_or(usize::MAX);
61	
62	        // `take` stops without polling upstream again after the Nth item, so
63	        // the count only increments for events that are actually yielded.
64	        let limited = stream
65	            .map(move |event| {
66	                count.fetch_add(1, Ordering::Relaxed);
67	                event
68	            })
69	            .take(limit);
70	
71	        Ok(Box::pin(limited))
72	    }
73	
74	    fn name(&self) -> &str {
75	        "MaxEventsLimiter"
76	    }
77	}
