//! FakeRunner-based pipeline tests for `--max-events`.
//!
//! These run without root or eBPF. The chain mirrors production wiring:
//! runner analyzers -> (filters) -> FileLogger -> OutputAnalyzer -> MaxEventsLimiter,
//! i.e. the limiter counts *logged* events at the very end of the chain.

use super::{Analyzer, AnalyzerError, FileLogger, MaxEventsLimiter, OutputAnalyzer};
use crate::framework::core::Event;
use crate::framework::runners::{EventStream, FakeRunner, Runner};
use async_trait::async_trait;
use futures::stream::StreamExt;
use std::time::{Duration, Instant};
use tempfile::NamedTempFile;

/// Drops requests (WRITE/SEND) so only responses (READ/RECV) survive.
struct DropRequests;

#[async_trait]
impl Analyzer for DropRequests {
    async fn process(&mut self, stream: EventStream) -> Result<EventStream, AnalyzerError> {
        Ok(Box::pin(stream.filter(|e: &Event| {
            futures::future::ready(e.data["function"] == "READ/RECV")
        })))
    }

    fn name(&self) -> &str {
        "DropRequests"
    }
}

fn log_lines(file: &NamedTempFile) -> Vec<String> {
    std::fs::read_to_string(file.path())
        .unwrap()
        .lines()
        .map(|s| s.to_string())
        .collect()
}

/// Run a stream to completion, failing the test if it does not terminate.
async fn collect_with_timeout(stream: EventStream, secs: u64) -> Vec<Event> {
    tokio::time::timeout(Duration::from_secs(secs), stream.collect::<Vec<_>>())
        .await
        .expect("stream did not terminate in time")
}

#[tokio::test]
async fn limiter_emits_exactly_n_to_logger_and_stream_terminates() {
    let log = NamedTempFile::new().unwrap();
    // 10 pairs = 20 events available, limit is 7 (odd, splits a pair).
    let mut runner = FakeRunner::new()
        .event_count(10)
        .delay_ms(4)
        .add_analyzer(Box::new(FileLogger::new(log.path()).unwrap()))
        .add_analyzer(Box::new(OutputAnalyzer::new()))
        .add_analyzer(Box::new(MaxEventsLimiter::new(7)));

    let events = collect_with_timeout(runner.run().await.unwrap(), 10).await;

    assert_eq!(events.len(), 7, "exactly N events reach the end of the stream");
    assert_eq!(log_lines(&log).len(), 7, "exactly N events were logged to file");
}

#[tokio::test]
async fn limiter_of_one_stops_after_first_event() {
    let log = NamedTempFile::new().unwrap();
    let mut runner = FakeRunner::new()
        .event_count(3)
        .delay_ms(4)
        .add_analyzer(Box::new(FileLogger::new(log.path()).unwrap()))
        .add_analyzer(Box::new(MaxEventsLimiter::new(1)));

    let events = collect_with_timeout(runner.run().await.unwrap(), 10).await;

    assert_eq!(events.len(), 1);
    assert_eq!(events[0].data["function"], "WRITE/SEND", "first generated event is kept");
    assert_eq!(log_lines(&log).len(), 1);
}

#[tokio::test]
async fn limit_counts_post_filter_events() {
    let log = NamedTempFile::new().unwrap();
    // 10 pairs; the filter drops all 10 requests, leaving 10 responses.
    // Limit 4 must therefore yield 4 *responses* (not 4 raw events, which
    // would have been 2 responses).
    let mut runner = FakeRunner::new()
        .event_count(10)
        .delay_ms(4)
        .add_analyzer(Box::new(DropRequests))
        .add_analyzer(Box::new(FileLogger::new(log.path()).unwrap()))
        .add_analyzer(Box::new(MaxEventsLimiter::new(4)));

    let events = collect_with_timeout(runner.run().await.unwrap(), 10).await;

    assert_eq!(events.len(), 4);
    assert!(events.iter().all(|e| e.data["function"] == "READ/RECV"));
    let lines = log_lines(&log);
    assert_eq!(lines.len(), 4);
    assert!(lines.iter().all(|l| l.contains("READ/RECV") && !l.contains("WRITE/SEND")));
}

#[tokio::test]
async fn limiter_larger_than_available_events_passes_all_and_ends() {
    let log = NamedTempFile::new().unwrap();
    let limiter = MaxEventsLimiter::new(1000);
    let counter = limiter.counter();
    let mut runner = FakeRunner::new()
        .event_count(3) // 6 events
        .delay_ms(4)
        .add_analyzer(Box::new(FileLogger::new(log.path()).unwrap()))
        .add_analyzer(Box::new(limiter));

    let events = collect_with_timeout(runner.run().await.unwrap(), 10).await;

    assert_eq!(events.len(), 6);
    assert_eq!(log_lines(&log).len(), 6);
    assert_eq!(counter.load(std::sync::atomic::Ordering::Relaxed), 6);
}

#[tokio::test]
async fn limiter_stops_early_without_draining_upstream() {
    // Upstream would take ~1000 * (delay + delay/4) = ~25s+ to finish.
    // Stopping after 3 events must return quickly.
    let mut runner = FakeRunner::new()
        .event_count(1000)
        .delay_ms(20)
        .add_analyzer(Box::new(MaxEventsLimiter::new(3)));

    let start = Instant::now();
    let events = collect_with_timeout(runner.run().await.unwrap(), 5).await;

    assert_eq!(events.len(), 3);
    assert!(
        start.elapsed() < Duration::from_secs(3),
        "limiter must terminate the stream promptly, took {:?}",
        start.elapsed()
    );
}

#[tokio::test]
async fn limiter_counter_matches_events_seen() {
    let limiter = MaxEventsLimiter::new(5);
    let counter = limiter.counter();
    let mut runner = FakeRunner::new()
        .event_count(10)
        .delay_ms(4)
        .add_analyzer(Box::new(limiter));

    let events = collect_with_timeout(runner.run().await.unwrap(), 10).await;

    assert_eq!(events.len(), 5);
    assert_eq!(counter.load(std::sync::atomic::Ordering::Relaxed), 5);
}

#[tokio::test]
async fn unlimited_pipeline_passes_everything_through() {
    // No limiter in the chain == flag absent == unlimited.
    let log = NamedTempFile::new().unwrap();
    let mut runner = FakeRunner::new()
        .event_count(10) // 20 events
        .delay_ms(4)
        .add_analyzer(Box::new(FileLogger::new(log.path()).unwrap()))
        .add_analyzer(Box::new(OutputAnalyzer::new()));

    let events = collect_with_timeout(runner.run().await.unwrap(), 10).await;

    assert_eq!(events.len(), 20);
    assert_eq!(log_lines(&log).len(), 20);
}

#[tokio::test]
async fn limit_equal_to_available_events_passes_all() {
    let log = NamedTempFile::new().unwrap();
    let mut runner = FakeRunner::new()
        .event_count(4) // 8 events
        .delay_ms(4)
        .add_analyzer(Box::new(FileLogger::new(log.path()).unwrap()))
        .add_analyzer(Box::new(MaxEventsLimiter::new(8)));

    let events = collect_with_timeout(runner.run().await.unwrap(), 10).await;

    assert_eq!(events.len(), 8);
    assert_eq!(log_lines(&log).len(), 8);
}

