//! Tests for the embedded web server, focused on `GET /api/config`.
//!
//! The server binds its own listener internally, so tests reserve a free
//! loopback port, start the server on it, and issue a raw HTTP/1.1 request.
//! No root or eBPF is required.

use crate::framework::core::Event;
use crate::server::WebServer;
use std::net::SocketAddr;
use std::time::Duration;
use tokio::io::{AsyncReadExt, AsyncWriteExt};
use tokio::net::TcpStream;
use tokio::sync::broadcast;

/// Reserve a free loopback port (small race window between drop and rebind).
fn free_addr() -> SocketAddr {
    let l = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
    l.local_addr().unwrap()
}

/// Perform a raw HTTP GET; returns (status line, headers lowercased, body).
async fn http_get(addr: SocketAddr, path: &str) -> (String, String, String) {
    let mut stream = None;
    for _ in 0..50 {
        match TcpStream::connect(addr).await {
            Ok(s) => {
                stream = Some(s);
                break;
            }
            Err(_) => tokio::time::sleep(Duration::from_millis(50)).await,
        }
    }
    let mut stream = stream.expect("server did not start listening");
    let req = format!("GET {} HTTP/1.1\r\nHost: localhost\r\nConnection: close\r\n\r\n", path);
    stream.write_all(req.as_bytes()).await.unwrap();

    let mut buf = Vec::new();
    tokio::time::timeout(Duration::from_secs(5), stream.read_to_end(&mut buf))
        .await
        .expect("response timed out")
        .unwrap();
    let text = String::from_utf8_lossy(&buf).to_string();
    let (head, body) = text.split_once("\r\n\r\n").expect("malformed HTTP response");
    let mut lines = head.lines();
    let status = lines.next().unwrap().to_string();
    let headers = lines.collect::<Vec<_>>().join("\n").to_lowercase();
    (status, headers, body.to_string())
}

async fn config_body(max_events: Option<u64>) -> (String, String, serde_json::Value) {
    let (tx, _rx) = broadcast::channel::<Event>(16);
    let server = WebServer::new(tx, None)
        .unwrap()
        .with_max_events(max_events);
    let addr = free_addr();
    let handle = tokio::spawn(async move {
        let _ = server.start(addr).await;
    });

    let (status, headers, body) = http_get(addr, "/api/config").await;
    handle.abort();
    let json: serde_json::Value = serde_json::from_str(&body)
        .unwrap_or_else(|e| panic!("body is not JSON ({}): {:?}", e, body));
    (status, headers, json)
}

#[tokio::test]
async fn api_config_reports_max_events_value() {
    let (status, headers, json) = config_body(Some(42)).await;
    assert!(status.contains("200"), "unexpected status: {}", status);
    assert!(headers.contains("application/json"), "headers: {}", headers);
    assert_eq!(json, serde_json::json!({"max_events": 42}));
}

#[tokio::test]
async fn api_config_reports_null_when_unlimited() {
    let (status, _headers, json) = config_body(None).await;
    assert!(status.contains("200"), "unexpected status: {}", status);
    assert!(json.get("max_events").is_some(), "key must be present, not omitted");
    assert!(json["max_events"].is_null());
}

