//! clap parsing tests for `--max-events <N>` on `record` and `trace`.
//! Pure argument parsing: no root, no eBPF, no binary extraction.

use crate::{Cli, Commands};
use clap::Parser;

fn parse(args: &[&str]) -> Result<Cli, clap::Error> {
    let mut full = vec!["agentsight"];
    full.extend_from_slice(args);
    Cli::try_parse_from(full)
}

fn record_max(args: &[&str]) -> Option<String> {
    match parse(args).expect("should parse").command {
        Commands::Record { max_events, .. } => max_events.map(|n| n.to_string()),
        _ => panic!("expected Record subcommand"),
    }
}

fn trace_max(args: &[&str]) -> Option<String> {
    match parse(args).expect("should parse").command {
        Commands::Trace { max_events, .. } => max_events.map(|n| n.to_string()),
        _ => panic!("expected Trace subcommand"),
    }
}

#[test]
fn record_accepts_max_events() {
    assert_eq!(record_max(&["record", "-c", "claude", "--max-events", "5"]), Some("5".into()));
}

#[test]
fn record_accepts_equals_form_and_large_values() {
    assert_eq!(record_max(&["record", "-c", "claude", "--max-events=1"]), Some("1".into()));
    assert_eq!(
        record_max(&["record", "-c", "claude", "--max-events", "18446744073709551615"]),
        Some("18446744073709551615".into())
    );
}

#[test]
fn record_defaults_to_unlimited() {
    assert_eq!(record_max(&["record", "-c", "claude"]), None);
}

#[test]
fn record_rejects_zero() {
    assert!(parse(&["record", "-c", "claude", "--max-events", "0"]).is_err());
}

#[test]
fn record_rejects_non_numeric_negative_empty_and_missing() {
    for bad in ["abc", "-1", "1.5", "", "5x", "99999999999999999999999"] {
        assert!(
            parse(&["record", "-c", "claude", "--max-events", bad]).is_err(),
            "record should reject --max-events {:?}",
            bad
        );
    }
    assert!(parse(&["record", "-c", "claude", "--max-events"]).is_err(), "missing value");
}

#[test]
fn trace_accepts_max_events() {
    assert_eq!(trace_max(&["trace", "--max-events", "5"]), Some("5".into()));
    assert_eq!(trace_max(&["trace", "--max-events=250"]), Some("250".into()));
}

#[test]
fn trace_accepts_max_events_with_other_flags() {
    assert_eq!(
        trace_max(&["trace", "--ssl", "true", "--process", "false", "-c", "python", "--server", "--max-events", "7"]),
        Some("7".into())
    );
}

#[test]
fn trace_defaults_to_unlimited() {
    assert_eq!(trace_max(&["trace"]), None);
}

#[test]
fn trace_rejects_zero() {
    assert!(parse(&["trace", "--max-events", "0"]).is_err());
}

#[test]
fn trace_rejects_non_numeric_negative_empty_and_missing() {
    for bad in ["abc", "-1", "1.5", "", "5x", "99999999999999999999999"] {
        assert!(
            parse(&["trace", "--max-events", bad]).is_err(),
            "trace should reject --max-events {:?}",
            bad
        );
    }
    assert!(parse(&["trace", "--max-events"]).is_err(), "missing value");
}

#[test]
fn zero_rejection_message_mentions_the_option() {
    let err = parse(&["trace", "--max-events", "0"]).err().unwrap().to_string();
    assert!(err.contains("max-events"), "error should name the option: {}", err);
}

